217: function doInteract() {
218:   const dir = new THREE.Vector3();
219:   camera.getWorldDirection(dir);
220:   const pos = camera.position.clone();
221:   let best = null, bestD = 1e9;
222:   for (const it of interactables) {
223:     const v = it.mesh.position.clone().sub(pos);
224:     const fwd = v.dot(dir);
225:     if (fwd < 0.6 || fwd > it.dist) continue;
226:     const vh = v.clone(); vh.y = 0; vh.normalize();
227:     const dh = dir.clone(); dh.y = 0; dh.normalize();
228:     const ang = Math.acos(Math.max(-1, Math.min(1, vh.dot(dh))));
229:     if (ang > 0.95) continue;
230:     if (fwd < bestD) { bestD = fwd; best = it; }
231:   }
232:   if (best) showMessage(best.text + ' — ' + (best.mesh.userData.open ? '열림' : '잠김'));
233:   else showMessage('상호작용할 대상이 없습니다.');
