199:   const rack = new THREE.Mesh(new THREE.BoxGeometry(3.2, 0.5, 0.5), new THREE.MeshStandardMaterial({ color: 0x3e2723 }));
200:   rack.position.set(0, 0.4, 1.2);
201:   rack.receiveShadow = true;
202:   scene.add(rack);
