213: /* ---------- input ---------- */
214: function onKeyDown(e) {
215:   if (e.code === 'KeyF') {
216:     flashlightOn = !flashlightOn;
217:     flashlight.intensity = flashlightOn ? 3.2 : 0;
218:     flashStateEl.textContent = flashlightOn ? 'ON' : 'OFF';
219:     return;
220:   }
221:   if (e.code === 'Escape') { controls.unlock(); return; }
222:   if (e.code === 'KeyE') { doInteract(); return; }
223:   if (!isLocked && e.code !== 'KeyW' && e.code !== 'KeyS' && e.code !== 'KeyA' && e.code !== 'KeyD') return;
224: 
225:   switch (e.code) {
226:     case 'KeyW': move.forward = 1; break;
227:     case 'KeyS': move.backward = 1; break;
228:     case 'KeyA': move.left = 1; break;
229:     case 'KeyD': move.right = 1; break;
230:     case 'ShiftLeft': isSprinting = true; break;
231:   }
232: }
233: function onKeyUp(e) {
234:   switch (e.code) {
235:     case 'KeyW': move.forward = 0; break;
236:     case 'KeyS': move.backward = 0; break;
237:     case 'KeyA': move.left = 0; break;
238:     case 'KeyD': move.right = 0; break;
239:     case 'ShiftLeft': isSprinting = false; break;
240:   }
241: }
242: 
243: /* ---------- mobile touch camera ---------- */
244: function onTouchStart(e) {
245:   e.preventDefault();
246:   lastTouchX = e.touches[0].clientX;
247:   lastTouchY = e.touches[0].clientY;
248: }
249: 
250: function onTouchMove(e) {
251:   e.preventDefault();
252:   const dx = e.touches[0].clientX - lastTouchX;
253:   const dy = e.touches[0].clientY - lastTouchY;
254: 
255:   touchYaw -= dx * TOUCH_SENSITIVITY;
256:   touchPitch -= dy * TOUCH_SENSITIVITY;
257: 
258:   // 상하 과도 회전 방지 (약 +/- 85도)
259:   const limit = Math.PI / 2 - 0.05;
260:   touchPitch = Math.max(-limit, Math.min(limit, touchPitch));
261: 
262:   lastTouchX = e.touches[0].clientX;
263:   lastTouchY = e.touches[0].clientY;
264: }
265: 
266: function onTouchEnd(e) {
267:   e.preventDefault();
268: }
269: function onResize() {
270:   camera.aspect = window.innerWidth / window.innerHeight;
271:   camera.updateProjectionMatrix();
272:   renderer.setSize(window.innerWidth, window.innerHeight);
273: }
274: 
275: /* ---------- interaction ---------- */
276: function doInteract() {
277:   const dir = new THREE.Vector3();
278:   camera.getWorldDirection(dir);
279:   const pos = camera.position.clone();
280:   let best = null, bestD = 1e9;
281:   for (const it of interactables) {
282:     const v = it.mesh.position.clone().sub(pos);
283:     const fwd = v.dot(dir);
284:     if (fwd < 0.6 || fwd > it.dist) continue;
285:     const vh = v.clone(); vh.y = 0; vh.normalize();
286:     const dh = dir.clone(); dh.y = 0; dh.normalize();
287:     const ang = Math.acos(Math.max(-1, Math.min(1, vh.dot(dh))));
288:     if (ang > 0.95) continue;
289:     if (fwd < bestD) { bestD = fwd; best = it; }
290:   }
291:   if (best) showMessage(best.text + ' — ' + (best.mesh.userData.open ? '열림' : '잠김'));
292:   else showMessage('상호작용할 대상이 없습니다.');
293: }
294: 
295: function showMessage(t) {
296:   msgEl.textContent = t;
297:   msgEl.classList.remove('hidden');
298:   msgTimer = 110;
299: }
300: 
301: /* ---------- suspicion / disguise mechanic ---------- */
302: function updateSuspicion() {
303:   const moving = move.forward || move.backward || move.left || move.right;
304:   if (isLocked && moving) {
305:     suspicion += isSprinting ? 1.1 : 0.25;
306:   } else {
307:     suspicion = Math.max(0, suspicion - 0.12);
308:   }
309:   suspicion = Math.min(100, suspicion);
310:   suspicionFill.style.width = suspicion + '%';
311:   suspicionFill.style.backgroundColor =
312:     suspicion > 70 ? '#ef4444' : suspicion > 40 ? '#f59e0b' : '#22c55e';
313:   if (suspicion >= 100 && Math.random() < 0.02) showMessage('복도를 순회하는 인영이 당신을 주시합니다.');
314: }
315: 
316: /* ---------- ambience ---------- */
317: function flickerLights(lights) {
318:   for (const pl of lights) {
319:     if (Math.random() < 0.25) pl.intensity = 0.5 + Math.random() * 0.6;
320:   }
321: }
322: 
323: /* ---------- main loop ---------- */
324: function animate() {
325:   requestAnimationFrame(animate);
326:   const now = performance.now();
327:   const dt = Math.min(0.05, (now - prevTime) / 1000);
328:   prevTime = now;
329: 
330:   const isPointerLocked = controls ? controls.isLocked : false;
331:   const isActive = isPointerLocked || (isMobile && isLocked);
332: 
333:   if (isActive) {
334:     const speed = isSprinting ? SPRINT : SPEED;
335:     const dir = new THREE.Vector3(move.left - move.right, 0, move.forward - move.backward);
336:     if (dir.lengthSq() > 0) {
337:       dir.normalize();
338:       // move relative to camera facing
339:       const forward = new THREE.Vector3();
340:       camera.getWorldDirection(forward);
341:       forward.y = 0; forward.normalize();
342:       const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));
343:       const offset = forward.clone().multiplyScalar(-dir.z).add(right.clone().multiplyScalar(dir.x));
344:       camera.position.add(offset.multiplyScalar(speed * dt));
345:     }
346:     camera.position.y = PLAYER_HEIGHT;
347:     // keep inside school bounds
348:     camera.position.x = Math.max(-20, Math.min(20, camera.position.x));
349:     camera.position.z = Math.max(-26, Math.min(3, camera.position.z));
350: 
351:     if (isMobile) {
352:       // 모바일 터치 카메라 회전 적용
353:       camera.rotation.set(touchPitch, touchYaw, 0);
354:       camera.rotation.order = 'YXZ';
355:       camera.updateMatrixWorld();
356:     }
357: 
358:     // 학생 NPC 업데이트 (시선 반응 이동)
359:     npcManager.update(camera, dt);
360:   }
361: 
362:   if (msgTimer > 0) { msgTimer--; if (msgTimer === 0) msgEl.classList.add('hidden'); }
363: 
364:   updateSuspicion();
365:   renderer.render(scene, camera);
366: }
367: 
368: init();

