content.text:
이제 `src/game.js`에 버튼 이벤트 리스너와 로직을 추가해야 합니다.

1. 전역 변수에 버튼 요소 참조 변수 추가
2. `init()`에서 버튼 요소 참조, 모바일일 때 이벤트 리스너 등록, 조이스틱 중심점 계산 이후 버튼 중심점 계산
3. `onTouchStart/Move/End`에서 버튼 영역 터치는 카메라 회전에서 제외
4. 버튼 클릭 핸들러 추가: 상호작용 버튼은 `doInteract()`, 손전등 버튼은 기존 F키 토글 로직 재사용
5. `animate()`에서 손전등 방향을 카메라 정면 방향으로 업데이트

버튼 영역 판정 함수 추가:

```javascript
function isInButtonArea(clientX, clientY) {
  const rect = canvas.getBoundingClientRect();
  const btnSize = Math.min(rect.width * 0.15, 100);
  const margin = Math.min(rect.width * 0.05, 20);
  // 오른쪽 아래 영역
  return clientX >= rect.left + rect.width - btnSize - margin &&
         clientX <= rect.left + rect.width - margin &&
         clientY >= rect.top + rect.height - btnSize * 2 - margin * 2 &&
         clientY <= rect.top + rect.height - margin;
}
```

더 간단하게, 버튼 영역의 바운딩 박스를 계산해서 사용해도 됩니다. 하지만 버튼은 DOM 요소이므로 `getBoundingClientRect()`를 사용할 수 있습니다.

`init()`에서:

```javascript
// 모바일 버튼 요소 참조
const btnInteract = document.getElementById('btn-interact');
const btnFlashlight = document.getElementById('btn-flashlight');

if (isMobile) {
  // 버튼 이벤트 리스너
  btnInteract.addEventListener('touchstart', (e) => {
    e.preventDefault();
    doInteract();
  });
  btnFlashlight.addEventListener('touchstart', (e) => {
    e.preventDefault();
    flashlightOn = !flashlightOn;
    flashlight.intensity = flashlightOn ? 3.2 : 0;
    flashStateEl.textContent = flashlightOn ? 'ON' : 'OFF';
    btnFlashlight.className = 'mobile-btn ' + (flashlightOn ? 'flashlight-on' : 'flashlight-off');
  });

  // click도 지원 (일부 브라우저)
  btnInteract.addEventListener('click', (e) => {
    e.preventDefault();
    doInteract();
  });
  btnFlashlight.addEventListener('click', (e) => {
    e.preventDefault();
    flashlightOn = !flashlightOn;
    flashlight.intensity = flashlightOn ? 3.2 : 0;
    flashStateEl.textContent = flashlightOn ? 'ON' : 'OFF';
    btnFlashlight.className = 'mobile-btn ' + (flashlightOn ? 'flashlight-on' : 'flashlight-off');
  });
}
```

하지만 `touchstart`에서 `preventDefault()`를 하면 `click`이 발생하지 않을 수 있으므로, `touchstart`만 처리하는 것이 나을 수 있습니다. 또는 `click`만 처리해도 됩니다. 모바일에서는 `touchstart`가 더 즉각적입니다.

버튼 영역을 카메라 입력에서 제외하려면, `onTouchStart/Move/End`에서 버튼 영역 터치를 필터링해야 합니다. `isInButtonArea` 함수를 추가하고, 조이스틱 영역과 마찬가지로 버튼 영역 터치는 카메라 회전 계산에서 제외합니다.

`onTouchStart` 수정:
```javascript
function onTouchStart(e) {
  e.preventDefault();
  for (const t of e.changedTouches) {
    activeTouches.set(t.identifier, { clientX: t.clientX, clientY: t.clientY });
    if (joystickTouchId === null && isInJoystickArea(t.clientX, t.clientY)) {
      joystickTouchId = t.identifier;
      updateJoystickVisual(t.clientX, t.clientY);
    } else if (isInButtonArea(t.clientX, t.clientY)) {
      // 버튼 영역 터치는 카메라 입력에서 제외 (버튼 핸들러가 처리함)
      // activeTouches에는 기록하되 카메라 회전에는 사용하지 않음
    } else if (joystickTouchId !== t.identifier) {
      lastTouchX = t.clientX;
      lastTouchY = t.clientY;
    }
  }
}
```

`onTouchMove` 수정:
```javascript
function onTouchMove(e) {
  e.preventDefault();
  let cameraTouch = null;
  for (const t of e.changedTouches) {
    activeTouches.set(t.identifier, { clientX: t.clientX, clientY: t.clientY });
    if (t.identifier === joystickTouchId) {
      updateJoystickVisual(t.clientX, t.clientY);
    } else if (!isInButtonArea(t.clientX, t.clientY)) {
      cameraTouch = t;
    }
  }
  // ... 카메라 회전 로직 ...
}
```

손전등 방향 업데이트: `animate()`에서
```javascript
if (flashlight) {
  const target = new THREE.Vector3();
  camera.getWorldDirection(target);
  target.multiplyScalar(30);
  target.add(camera.position);
  flashlight.target.position.copy(target);
  flashlight.target.updateMatrixWorld();
}
```

