345: /* ---------- mobile touch camera & joystick ---------- */
346: function onTouchStart(e) {
347:   e.preventDefault();
348:   for (const t of e.changedTouches) {
349:     activeTouches.set(t.identifier, { clientX: t.clientX, clientY: t.clientY });
350:     if (joystickTouchId === null && isInJoystickArea(t.clientX, t.clientY)) {
351:       joystickTouchId = t.identifier;
352:       updateJoystickVisual(t.clientX, t.clientY);
353:     } else if (isInButtonArea(t.clientX, t.clientY)) {
354:       // 버튼 영역 터치는 카메라 입력에서 제외 (버튼 핸들러가 처리함)
355:     } else if (joystickTouchId !== t.identifier) {
356:       // 카메라용 터치 시작 위치 기록
357:       lastTouchX = t.clientX;
358:       lastTouchY = t.clientY;
359:     }
360:   }
361: }
