363: function onTouchMove(e) {
364:   e.preventDefault();
365:   let cameraTouch = null;
366:   let cameraPrev = null;
367: 
368:   for (const t of e.changedTouches) {
369:     // 새 위치로 덮어쓰기 전에 이전 위치를 먼저 가져온다
370:     const prev = activeTouches.get(t.identifier);
371:     activeTouches.set(t.identifier, { clientX: t.clientX, clientY: t.clientY });
372: 
373:     if (t.identifier === joystickTouchId) {
374:       updateJoystickVisual(t.clientX, t.clientY);
375:     } else if (!isInButtonArea(t.clientX, t.clientY)) {
376:       cameraTouch = t;
377:       cameraPrev = prev; // 카메라 터치의 이전 위치 보존
378:     }
379:   }
380: 
381:   // 카메라 회전 (조이스틱이나 버튼이 아닌 터치 중 하나)
382:   if (cameraTouch && cameraPrev) {
383:     const dx = cameraTouch.clientX - cameraPrev.clientX;
384:     const dy = cameraTouch.clientY - cameraPrev.clientY;
385:     touchYaw -= dx * TOUCH_SENSITIVITY;
386:     touchPitch -= dy * TOUCH_SENSITIVITY;
387: 
388:     // 상하 과도 회전 방지 (약 +/- 85도)
389:     const limit = Math.PI / 2 - 0.05;
390:     touchPitch = Math.max(-limit, Math.min(limit, touchPitch));
391:   }
392: }
