409: /* ---------- interaction ---------- */
410: function doInteract() {
411:   const dir = new THREE.Vector3();
412:   camera.getWorldDirection(dir);
413:   const pos = camera.position.clone();
414:   let best = null, bestD = 1e9;
415:   for (const it of interactables) {
416:     const v = it.mesh.position.clone().sub(pos);
417:     const fwd = v.dot(dir);
418:     if (fwd < 0.6 || fwd > it.dist) continue;
419:     const vh = v.clone(); vh.y = 0; vh.normalize();
420:     const dh = dir.clone(); dh.y = 0; dh.normalize();
421:     const ang = Math.acos(Math.max(-1, Math.min(1, vh.dot(dh))));
422:     if (ang > 0.95) continue;
423:     if (fwd < bestD) { bestD = fwd; best = it; }
424:   }
425:   if (best) showMessage(best.text + ' — ' + (best.mesh.userData.open ? '열림' : '잠김'));
426:   else showMessage('상호작용할 대상이 없습니다.');
427: }
