446:     suspicion > 70 ? '#ef4444' : suspicion > 40 ? '#f59e0b' : '#22c55e';
447:   if (suspicion >= 100 && Math.random() < 0.02) showMessage('복도를 순회하는 인영이 당신을 주시합니다.');
