457: /* ---------- main loop ---------- */
458: function animate() {
459:   requestAnimationFrame(animate);
460:   const now = performance.now();
461:   const dt = Math.min(0.05, (now - prevTime) / 1000);
462:   prevTime = now;
463: 
464:   const isPointerLocked = controls ? controls.isLocked : false;
465:   const isActive = isPointerLocked || (isMobile && isLocked);
466: 
467:   if (isActive) {
468:     const speed = isSprinting ? SPRINT : SPEED;
469: 
470:     if (isMobile && (Math.abs(joystickVec.x) > 0.15 || Math.abs(joystickVec.y) > 0.15)) {
471:       // ---------- 모바일: 가상 조이스틱 이동 ----------
472:       // 조이스틱 입력 정규화 (대각선 속도 보정)
473:       const joyLen = Math.sqrt(joystickVec.x * joystickVec.x + joystickVec.y * joystickVec.y);
474:       const nx = joystickVec.x / joyLen;           // 화면 오른쪽 = 양수 (카메라 우측)
475:       const ny = -joystickVec.y / joyLen;          // 화면 위쪽 = 양수 (카메라 전방, 화면 좌표계 반전)
476: 
477:       // 카메라 기준 수평 전방 벡터 (y=0 고정)
478:       const forward = new THREE.Vector3();
479:       camera.getWorldDirection(forward);
480:       forward.y = 0;
481:       forward.normalize();
482: 
483:       // 카메라 기준 우측 벡터
484:       const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));
485: 
486:       // 월드 이동 방향 = 카메라 전방 * ny + 카메라 우측 * nx
487:       const worldMove = new THREE.Vector3();
488:       worldMove.addScaledVector(forward, ny);
489:       worldMove.addScaledVector(right, nx);
490:       worldMove.normalize();
491: 
492:       const nextPos = camera.position.clone().addScaledVector(worldMove, speed * dt);
493:       camera.position.x = Math.max(-20, Math.min(20, nextPos.x));
494:       camera.position.z = Math.max(-26, Math.min(3, nextPos.z));
495:       camera.position.y = PLAYER_HEIGHT;
496: 
497:       // WASD 입력 잔여값 초기화 (모바일에서는 사용하지 않음)
498:       move.forward = 0;
499:       move.backward = 0;
500:       move.left = 0;
501:       move.right = 0;
502:     } else {
503:       // ---------- 데스크톱: WASD 이동 (기존 로직 유지) ----------
504:       const dir = new THREE.Vector3(move.left - move.right, 0, move.forward - move.backward);
505:       if (dir.lengthSq() > 0) {
506:         dir.normalize();
507:         const forward = new THREE.Vector3();
508:         camera.getWorldDirection(forward);
509:         forward.y = 0;
510:         forward.normalize();
511:         const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));
512:         const offset = forward.clone().multiplyScalar(-dir.z).add(right.clone().multiplyScalar(dir.x));
513:         camera.position.add(offset.multiplyScalar(speed * dt));
514:       }
515:       camera.position.y = PLAYER_HEIGHT;
516:       camera.position.x = Math.max(-20, Math.min(20, camera.position.x));
517:       camera.position.z = Math.max(-26, Math.min(3, camera.position.z));
518:     }
519: 
520:     if (isMobile) {
521:       // 모바일 터치 카메라 회전 적용
522:       camera.rotation.set(touchPitch, touchYaw, 0);
523:       camera.rotation.order = 'YXZ';
524:       camera.updateMatrixWorld();
525:     }
526: 
527:     // 손전등 위치와 방향을 카메라 기준으로 업데이트 (카메라 시선 방향을 따라감)
528:     if (flashlight) {
529:       flashlight.position.copy(camera.position);
530:       flashlight.position.y = PLAYER_HEIGHT - 0.05;
531:       const target = new THREE.Vector3();
532:       camera.getWorldDirection(target);
533:       target.multiplyScalar(30);
534:       target.add(camera.position);
535:       flashlight.target.position.copy(target);
536:       flashlight.target.updateMatrixWorld();
537:     }
538: 
539:     // 학생 NPC 업데이트 (시선 반응 이동)
540:     npcManager.update(camera, dt);
541:   }
542: 
543:   if (msgTimer > 0) { msgTimer--; if (msgTimer === 0) msgEl.classList.add('hidden'); }
544: 
545:   updateSuspicion();
546:   renderer.render(scene, camera);
547: }
