    const joyLen = Math.sqrt(joystickVec.x * joystickVec.x + joystickVec.y * joystickVec.y);
    const nx = joystickVec.x / joyLen;           // 화면 오른쪽 = 양수 (카메라 우측)
    const ny = -joystickVec.y / joyLen;          // 화면 위쪽 = 양수 (카메라 전방, 화면 좌표계 반전)

